const INK = "#2B2822";
const MUT = "#71695D";
const LINE = "#D8D2C3";
const GOLD = "#866430";
const RUBY = "#8E2C48";

/* La foto de un evento de verdad, de fondo. Va rebajada y desenfocada dentro
   del propio archivo (no con filtros CSS) por dos motivos: sale igual en todos
   los navegadores, y así pesa 44 KB en vez de 300 — la pantalla de entrada la
   abre todo el equipo desde el móvil, muchas veces con mala cobertura. */
const FONDO = "data:image/jpeg;base64,";

const LOGO = "data:image/png;base64,";

export default async function LoginPage({ searchParams }) {
  const sp = (await searchParams) || {};
  const wrong = sp.error === "1";

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
        boxSizing: "border-box",
        color: INK,
        fontFamily: "Karla, system-ui, sans-serif",
        position: "relative",
        overflow: "hidden",
        backgroundColor: "#1A1713",
      }}
    >
      {/* la foto */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: `url("${FONDO}")`,
          backgroundSize: "cover",
          backgroundPosition: "center 42%",
        }}
      />
      {/* un velo cálido: oscurece los bordes y deja el centro un poco más claro,
          para que la tarjeta se despegue del fondo sin tapar la foto del todo */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(120% 90% at 50% 45%, rgba(26,23,19,.18) 0%, rgba(26,23,19,.52) 55%, rgba(20,17,14,.78) 100%)",
        }}
      />

      <main
        style={{
          position: "relative",
          width: "100%",
          maxWidth: 372,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 20,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 11 }}>
          <img
            src={LOGO}
            alt=""
            width={40}
            height={40}
            style={{
              borderRadius: "50%",
              flex: "none",
              display: "block",
              boxShadow: "0 2px 10px rgba(0,0,0,.45)",
            }}
          />
          <div
            style={{
              fontFamily: "Cormorant Garamond, Georgia, serif",
              fontSize: 30,
              fontWeight: 600,
              color: "#F6F1E6",
              textShadow: "0 1px 12px rgba(0,0,0,.55)",
              lineHeight: 1.1,
            }}
          >
            Les Moles Events
          </div>
        </div>

        <form
          method="POST"
          action="/api/login"
          style={{
            width: "100%",
            /* sin esto el relleno se suma al 100% y en móvil la tarjeta se sale
               de la pantalla por los dos lados */
            boxSizing: "border-box",
            background: "rgba(251,250,246,.96)",
            border: `1px solid ${LINE}`,
            borderRadius: 12,
            padding: "26px 26px 24px",
            boxShadow: "0 18px 50px rgba(16,13,10,.45), 0 2px 6px rgba(16,13,10,.25)",
          }}
        >
          <div
            style={{
              fontSize: 9.5,
              letterSpacing: ".22em",
              textTransform: "uppercase",
              color: MUT,
              marginBottom: 18,
              textAlign: "center",
            }}
          >
            Acceso del equipo
          </div>

          <label
            htmlFor="password"
            style={{ fontSize: 12.5, color: MUT, display: "block", marginBottom: 6 }}
          >
            Contraseña del equipo
          </label>
          <input
            id="password"
            name="password"
            type="password"
            autoFocus
            required
            style={{
              width: "100%",
              boxSizing: "border-box",
              padding: "10px 11px",
              fontSize: 14,
              border: `1px solid ${LINE}`,
              borderRadius: 6,
              marginBottom: 14,
              background: "#fff",
              color: INK,
            }}
          />

          {wrong && (
            <p style={{ color: RUBY, fontSize: 12.5, margin: "0 0 14px" }}>
              Contraseña incorrecta. Inténtalo de nuevo.
            </p>
          )}

          <button
            type="submit"
            style={{
              width: "100%",
              padding: "11px 12px",
              fontSize: 13,
              fontWeight: 500,
              color: "#fff",
              background: GOLD,
              border: "none",
              borderRadius: 6,
              cursor: "pointer",
            }}
          >
            Entrar
          </button>
        </form>

        <div
          style={{
            fontSize: 10,
            letterSpacing: ".18em",
            textTransform: "uppercase",
            color: "rgba(246,241,230,.62)",
            textShadow: "0 1px 8px rgba(0,0,0,.6)",
          }}
        >
          Planos · Menús · Inventario
        </div>
      </main>
    </div>
  );
}
